  // Bucket records were once plain strings; upgrade on read so saved text survives.
  static partRecord(sec, id) {
    if (!sec.findingsParts) sec.findingsParts = {};
    const cur = sec.findingsParts[id];
    if (typeof cur === 'string' || cur == null) {
      sec.findingsParts[id] = { text: cur || '', status: 'Not started', redFlag: false };
    } else {
      if (typeof cur.text !== 'string') cur.text = '';
      if (!cur.status) cur.status = 'Not started';
      if (typeof cur.redFlag !== 'boolean') cur.redFlag = false;
      if (typeof cur.rating !== 'string') cur.rating = '';
    }
    return sec.findingsParts[id];
  }

  static partFlags(sec) {
    const p = sec.findingsParts || {};
    return Object.keys(p).filter((k) => p[k] && p[k].redFlag === true).length;
  }

  // A saved record belongs to the line of enquiry it was written against, not to a
  // position: when the template gains or reorders enquiries, match on the stored
  // enquiry text first, then hand any leftover records to the remaining slots in
  // order so a reworded enquiry still keeps its finding.
  static realignQuestions(src, t) {
    const stored = src && Array.isArray(src.questions) ? src.questions.slice() : [];
    const norm = (s) => String(s || '').replace(/\s+/g, ' ').trim().toLowerCase();
    const byText = new Map();
    stored.forEach((q, i) => {
      const k = norm(q && q.text);
      if (k && !byText.has(k)) byText.set(k, i);
    });
    const taken = new Set();
    const out = t.questions.map((text) => {
      const i = byText.get(norm(text));
      if (i != null && !taken.has(i)) { taken.add(i); return { text, q: stored[i] }; }
      return { text, q: null };
    });
    const spare = stored.map((q, i) => i).filter((i) => !taken.has(i) && stored[i]);
    // Only a pure rewording — same enquiry count, one spare record per empty slot — lets
    // records move by position. When an enquiry was added or removed, an unmatched record
    // belonged to an enquiry that no longer exists, so it is dropped rather than cascaded
    // into an unrelated slot.
    const empty = out.filter((slot) => !slot.q).length;
    if (spare.length && stored.length === t.questions.length && spare.length === empty) {
      out.forEach((slot) => {
        if (!slot.q && spare.length) slot.q = stored[spare.shift()];
      });
    }
    return out;
  }

