  static repairLicensing(sec) {
    const qs = sec && Array.isArray(sec.questions) ? sec.questions : null;
    if (!qs || qs.length !== 11) return;
    const slotOf = (prefix) => qs.findIndex((q) => q && String(q.text || '').startsWith(prefix));
    const home = new Map();
    Component.LICENSING_PAIRS.forEach(([finding, text]) => home.set(finding, slotOf(text)));
    const held = qs.map((q, i) => {
      const f = q && q.finding ? String(q.finding) : '';
      const pair = Component.LICENSING_PAIRS.find(([p]) => f.startsWith(p));
      return pair ? { at: i, to: home.get(pair[0]) } : null;
    }).filter((h) => h && h.to >= 0);
    if (!held.length || held.every((h) => h.at === h.to)) return;
    const payload = (q) => ({
      finding: q.finding || '', status: q.status || 'Not started', redFlag: !!q.redFlag,
      notes: q.notes || '', rating: q.rating != null ? q.rating : null, management: q.management || '',
    });
    const blank = { finding: '', status: 'Not started', redFlag: false, notes: '', rating: null, management: '' };
    const moved = held.map((h) => ({ to: h.to, val: payload(qs[h.at]) }));
    qs.forEach((q) => Object.assign(q, blank));
    moved.forEach(({ to, val }) => Object.assign(qs[to], val));
    Component.PROFILE_RECORDS.forEach(([status, finding, notes, prefix]) => {
      const i = slotOf(prefix);
      if (i >= 0) Object.assign(qs[i], { finding, status, notes });
    });
  }

